#!/usr/bin/env python3
"""Generate original M96 UI Showcase content using ordinary public asset formats."""
from pathlib import Path
import json,hashlib,shutil
R=Path(__file__).resolve().parents[1];P=R/'projects/ui_showcase'
P.mkdir(exist_ok=True)
def write(path,data):
 p=P/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n' if not isinstance(data,str) else data)
def aid(name):return hashlib.md5(('m96-ui-showcase/'+name).encode()).hexdigest()
def meta(path,kind):write(path+'.judasmeta',f'JudasAssetMeta 1\nid "{aid(path)}"\ntype {kind}\nsource "{path}"\n')
font='Assets/fonts/DejaVuSans.ttf';(P/font).parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(R/'projects/animation_studio'/font,P/font);shutil.copyfile(R/'projects/animation_studio/Assets/fonts/LICENSE.txt',P/'Assets/fonts/LICENSE.txt');meta(font,'font')
base=json.load(open(R/'projects/animation_studio/Assets/ui/studio.judasui'))['data']['elements'][0]
bg=[.035,.05,.075,1];card=[.065,.09,.13,1];muted=[.56,.64,.73,1];white=[.92,.94,.95,1];gold=[.98,.73,.29,1]
def element(id,parent,kind,x,y,w,h,text='',**kw):
 e=dict(base);e.update(id=id,parent=parent,kind=kind,flow=0,visible=True,enabled=True,clip=False,wrap=False,fit=True,anchorMin=[0,0],anchorMax=[0,0],offset=[x,y],size=[w,h],relativeSize=[0,0],align=[0,0],textAlign=[0,0],margin=[0,0,0,0],padding=[0,0,0,0],background=[0,0,0,0],color=white,font=aid(font),texture='',text=text,textKey='',direction=0,textLogicalAlign=-1,mirrorRow=False,spacing=8,fontSize=22,value=0,minimum=0,maximum=1,focusColor=gold,placeholder='',accessibleLabel=text,description='',readOnly=False,maxBytes=4096,rowHeight=44);
 if kind==4:e["textAlign"]=[.5,.5]
 e.update(kw);return e
es=[element('canvas','',0,0,0,1280,720,background=bg),element('brand','canvas',2,36,25,680,42,'JUDAS / FIELD NOTES',fontSize=30,color=gold),element('subtitle','canvas',2,38,72,1100,32,'UI SHOWCASE     /     Native text · Live content · Independent focus',fontSize=18,color=muted),element('nav','canvas',1,24,126,222,506,background=card)]
for n,(key,label) in enumerate([('menu','01   Welcome'),('settings','02   Settings'),('inventory','03   Inventory'),('dialogue','04   Dialogue'),('entry','05   Text entry'),('local','06   Local players')]):es.append(element('nav_'+key,'nav',4,12,12+n*64,198,50,label,background=[.1,.14,.2,1],fontSize=19))
es += [element('save','canvas',4,28,647,102,42,'SAVE',fontSize=17,background=card),element('load','canvas',4,142,647,102,42,'LOAD',fontSize=17,background=card),element('status','canvas',2,280,655,950,36,'Ready · click a section to explore',fontSize=17,color=muted,wrap=True)]
for key,title,description in [('menu','Interfaces with room to breathe','A working toolkit, with the game meaning left to JavaScript.'),('settings','Make it yours','Readable scale and clear focus. No animation required to use a control.'),('inventory','A thousand things, without a thousand widgets','Filter, add and select live keyed rows. Only visible rows are drawn.'),('dialogue','A conversation, at your pace','Scrollable text, selectable choices and an editable reply.'),('entry','Words belong here','Unicode, selection, clipboard, undo and native IME composition.'),('local','One world. Separate conversations.','Open two independently routed interface viewports.')]:
 es.extend([element(key,'canvas',1,270,126,984,506,visible=key=='menu',background=card),element(key+'_title',key,2,24,18,930,44,title,fontSize=28,color=gold),element(key+'_subtitle',key,2,24,68,930,48,description,fontSize=18,color=muted,wrap=True)])
es.extend([element('welcome','menu',2,28,145,800,154,'Welcome to Field Notes.\nTry the inventory, edit your name, or navigate without a mouse.\nEvery screen is an ordinary .judasui asset driven by project JS.',fontSize=24,wrap=True),element('explore','menu',4,28,340,360,58,'OPEN THE INVENTORY   →',background=[.19,.25,.29,1]),element('keys','menu',2,28,428,880,55,'Mouse / touch · Arrow keys · Tab · Enter · Gamepad D-pad / South',fontSize=18,color=muted)])
es.extend([element('scale_label','settings',2,28,140,430,36,'Interface scale',fontSize=23),element('scale','settings',5,28,195,540,38,value=1,minimum=.75,maximum=1.5,color=gold,background=bg),element('contrast','settings',6,28,265,540,52,'        High-contrast focus',background=bg),element('volume','settings',5,28,365,540,32,value=.7,minimum=0,maximum=1,color=[.4,.7,.8,1],background=bg),element('volume_label','settings',2,28,322,540,38,'Audio level (project setting)',fontSize=20)])
es.extend([element('filter','inventory',7,24,120,560,48,placeholder='Search salvage…',background=bg,accessibleLabel='Filter inventory'),element('add','inventory',4,614,120,336,48,'ADD SUPPLY CRATE',fontSize=18,background=bg),element('items','inventory',9,24,190,560,286,background=bg,rowHeight=44,accessibleLabel='Supply inventory'),element('detail','inventory',2,614,200,336,260,'Select a supply.\n\nKeys are stable when the list is filtered or refreshed.',fontSize=21,wrap=True)])
es.extend([element('conversation','dialogue',8,24,125,570,250,background=bg),element('story','conversation',2,16,12,530,800,'',fontSize=23,wrap=True),element('reply','dialogue',7,24,398,570,50,placeholder='Type a reply and press Enter',accessibleLabel='Dialogue reply',background=bg),element('choice','dialogue',9,620,125,330,250,rowHeight=72,background=bg,accessibleLabel='Dialogue choices'),element('dialogue_hint','dialogue',2,620,400,330,76,'Wheel / drag to revisit the conversation.',fontSize=19,color=muted,wrap=True)])
es.extend([element('name_label','entry',2,24,125,460,32,'DISPLAY NAME',fontSize=16,color=gold),element('name','entry',7,24,165,650,54,placeholder='Conner / café / مرحبا',background=bg,maxBytes=128,accessibleLabel='Display name'),element('note_label','entry',2,24,242,460,30,'FIELD NOTE',fontSize=16,color=gold),element('note','entry',7,24,282,650,54,placeholder='Single-line note, up to 512 UTF-8 bytes',maxBytes=512,background=bg,accessibleLabel='Field note'),element('readonly','entry',7,24,370,650,50,'Read only · select and copy me',readOnly=True,background=bg,accessibleLabel='Read-only example'),element('entry_hint','entry',2,700,162,244,300,'Ctrl+A / C / X / V\nCtrl+Z / Shift+Ctrl+Z\nShift+arrows select\nHome / End\n\nIME uses the platform keyboard.',fontSize=19,color=muted,wrap=True)])
es.extend([element('start_local','local',4,28,155,560,60,'OPEN TWO-PLAYER DESK',background=bg),element('local_help','local',2,28,250,870,175,'Player one: arrows / Enter and mouse.\nPlayer two: W / S / Space, or an assigned gamepad.\nAndroid: each half owns its own touch region.\nF1 returns to this shared interface.',fontSize=23,wrap=True)])
write('Assets/scripts/layout.js','export const layoutIds='+json.dumps([e['id'] for e in es])+';\n');meta('Assets/scripts/layout.js','script')
write('Assets/ui/showcase.judasui',{'kind':'ui','schema':1,'data':{'reference':[1280,720],'visible':True,'enabled':True,'modal':True,'elements':es}});meta('Assets/ui/showcase.judasui','ui')
local=[element('canvas','',0,0,0,640,720,background=bg),element('title','canvas',2,26,30,580,50,'YOUR FIELD DESK',fontSize=30,color=gold),element('hint','canvas',2,26,94,580,70,'Independent focus and item selection.\nClick the name field to type; F1 returns.',fontSize=19,wrap=True,color=muted),element('name','canvas',7,26,182,588,54,placeholder='Your callsign',accessibleLabel='Player callsign',background=card),element('items','canvas',9,26,266,588,310,background=card,accessibleLabel='Player supply inventory'),element('status','canvas',2,26,610,588,85,'Select an item',fontSize=21,wrap=True)]
write('Assets/ui/player.judasui',{'kind':'ui','schema':1,'data':{'reference':[640,720],'visible':True,'enabled':True,'modal':True,'elements':local}});meta('Assets/ui/player.judasui','ui')
project=json.load(open(R/'projects/animation_studio/animation_studio.judasproj'));data=project['data'];data.update(name='Judas / Field Notes',saveIdentity=hashlib.sha256(b'M96-Field-Notes').hexdigest(),startupScene='Scenes/showcase.judas',exportScenes=['Scenes/showcase.judas'],runtimeAssets=[aid(x) for x in ['Assets/ui/showcase.judasui','Assets/ui/player.judasui','Assets/scripts/showcase.js',font]])
def binding(name,axis,*controls):return dict(name=name,axis=axis,bindings=[dict(control=c,scale=1,deadzone=0)for c in controls])
data['input']=[binding('ui_up',False,'key:Up','pad:DpadUp'),binding('ui_down',False,'key:Down','pad:DpadDown'),binding('ui_left',False,'key:Left','pad:DpadLeft'),binding('ui_right',False,'key:Right','pad:DpadRight'),binding('ui_activate',False,'key:Return','pad:South'),binding('ui_next',False,'key:Tab','pad:RightShoulder'),binding('ui_click',False,'mouse:Left'),binding('ui_scroll',True,'mouse:wheelY'),binding('pause',False,'key:Escape','pad:Start'),binding('home',False,'key:F1'),binding('save',False,'key:F6'),binding('load',False,'key:F7')]
write('ui_showcase.judasproj',project)
scene=json.load(open(R/'projects/animation_studio/Scenes/studio.judas'));scene['data']['settings']['name']='Field Notes / UI Showcase';scene['data']['objects']=[{'id':1,'name':'Interface policy (project JS)','fields':{'position':[0,0,0],'rotation':[1,0,0,0],'scale':[1,1,1],'scripts':1,'script.0.id':1,'script.0.asset':aid('Assets/scripts/showcase.js'),'script.0.enabled':True,'script.0.properties':'{}','ui.asset':aid('Assets/ui/showcase.judasui'),'ui.name':'showcase','ui.enabled':True}}];write('Scenes/showcase.judas',scene);meta('Assets/scripts/showcase.js','script')
print(P)
